**C++ Node Definition**:

```cpp
struct Node {
    int data;     // Holds our actual value
    Node* next;   // Holds the memory address of the next Node
};
```

simulationData.code:
// Node nodes are allocated at scattered RAM addresses:
// Node A (at 0x100): data = 10, next = 0x300
// Node B (at 0x300): data = 20, next = 0x200
// Node C (at 0x200): data = 30, next = nullptr

Node* temp = head;
while (temp != nullptr) {
    std::cout << temp->data << " ";
    temp = temp->next;
}
